    @EventHandler( payloadType=CreateEnterpriseEvent.class )
    public void handle( CreateEnterpriseEvent event) {
	    LOGGER.info("handling CreateEnterpriseEvent - " + event );
	    Enterprise entity = new Enterprise();
            entity.setEnterpriseId( event.getEnterpriseId() );
            entity.setName( event.getName() );
            entity.setLegalName( event.getLegalName() );
            entity.setRegistrationCountry( event.getRegistrationCountry() );
            entity.setWebsite( event.getWebsite() );
            entity.setTaxId( event.getTaxId() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllEnterprise( entity );
    }

