    /**
     * Method to retrieve the Enterprise via an EnterprisePrimaryKey.
     * @param 	id Long
     * @return 	Enterprise
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Enterprise handle( FindEnterpriseQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getEnterpriseId() );
    }
    
    /**
     * Method to retrieve a collection of all Enterprises
     *
     * @param	query	FindAllEnterpriseQuery 
     * @return 	List<Enterprise> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Enterprise> handle( FindAllEnterpriseQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindEnterprise,
 * but only if the id matches
 *
 * @param		entity	Enterprise
 */
	protected void emitFindEnterprise( Enterprise entity ) {
		LOGGER.info("handling emitFindEnterprise" );
		
	    queryUpdateEmitter.emit(FindEnterpriseQuery.class,
	                            query -> query.getFilter().getEnterpriseId().equals(entity.getEnterpriseId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllEnterprise
	 * 
	 * @param		entity	Enterprise
	 */
	protected void emitFindAllEnterprise( Enterprise entity ) {
		LOGGER.info("handling emitFindAllEnterprise" );
		
	    queryUpdateEmitter.emit(FindAllEnterpriseQuery.class,
	                            query -> true,
	                            entity);
	}

